	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	t := readInt(reader)
	aa := make([]int, t)
	for i := 0; i < t; i++ {
		aa[i] = readInt(reader)
	}

	flag := 0
	a, b := 1, 2
	for i := 0; i < t; i++ {
		if aa[i] == a {
			b = 6 - (a + b)
		} else if aa[i] == b {
			a = 6 - (a + b)
		} else {
			flag = 1
			break
		}
	}

	if flag == 1 {
		fmt.Fprintln(writer, "NO")
	} else {
		fmt.Fprintln(writer, "YES")
	}
}

func readInt(reader *bufio.Reader) int {
	var n int
	fmt.Fscan(reader, &n)
	return n
}
